sample:
# lesson04 ch02: 文字列補間と演算子
# "${}" で文字列の中に式を埋め込めます。

variable "app" {
  type    = string
  default = "web"
}

variable "env" {
  type    = string
  default = "dev"
}

locals {
  # 実務で最頻出の「名前の組み立て」パターン
  name = "${var.app}-${var.env}"

  # 算術演算子も使えます
  total_gb = 20 * 2
}

output "resource_name" {
  value = local.name
}

output "total_gb" {
  value = local.total_gb
}

exercise.answer:
# "${式}" が文字列補間。実務の「プロジェクト名-環境名」の組み立てそのものです。
# 数値の計算は locals の右辺に演算子でそのまま書けます。
variable "app" {
  type    = string
  default = "billing"
}

variable "env" {
  type    = string
  default = "prod"
}

locals {
  name           = "${var.app}-${var.env}"
  total_capacity = 4 * 3
}

output "resource_name" {
  value = local.name
}

output "total_capacity" {
  value = local.total_capacity
}
